import re
C = student.get(cls)
_code = re.sub(r"#.*", "", student_code)
manque = [m for m in requis if not re.search(r"\." + m + r"\s*\(", _code)]
def _etat(o):
    return tuple(getattr(o, a, None) for a in attrs)
def _montre(vals):
    return cls + "(" + ", ".join(repr(x) for x in vals) + ")"
if not isinstance(C, type):
    check(False, f"la classe `{cls}` doit être définie")
elif not callable(getattr(C, mname, None)):
    check(False, f"la classe `{cls}` doit avoir une méthode `{mname}`")
elif manque:
    check(False, "Votre méthode doit **appeler** " + " et ".join(f"la méthode `{m}`" for m in manque)
          + " sur un objet (par exemple `self." + manque[0] + "(...)`), au lieu de refaire le calcul.")
else:
    for vals, args, ret, apres, apres_args in cases:
        o = C(*vals)
        objs = [C(*a[1]) if a[0] == "obj" else a[1] for a in args]
        appel = _montre(vals) + "." + mname + "(" + ", ".join(_montre(a[1]) if a[0] == "obj" else repr(a[1]) for a in args) + ")"
        try:
            r = getattr(o, mname)(*objs)
        except Exception as e:
            if type(e).__name__ == "TimeLimit":
                raise
            check(False, f"`{appel}` provoque une erreur : {erreur(e)}")
            continue
        if ret[0] == "obj":
            if type(r).__name__ != cls:
                check(False, f"`{appel}` doit renvoyer un **nouvel objet** `{cls}`, et non `{r!r}`")
            else:
                check_equal(_etat(r), ret[1], f"`{appel}` renvoie un objet dont les attributs ({', '.join(attrs)}) valent {_etat(r)} au lieu de {ret[1]}")
        else:
            check_equal(r, ret[1], f"`{appel}` renvoie `{r!r}` au lieu de `{ret[1]!r}`")
        if apres is not None:
            check_equal(_etat(o), apres, (f"après `{appel}`, les attributs ({', '.join(attrs)}) de l'objet valent {_etat(o)} au lieu de {apres}"
                        + ("" if modifie else " : cette méthode ne doit pas modifier l'objet")))
        for a, ob, att in zip(args, objs, apres_args):
            if att is not None:
                check_equal(_etat(ob), att, (f"après `{appel}`, les attributs de l'objet passé en argument valent {_etat(ob)} au lieu de {att}"
                        + ("" if modifie else " : il ne doit pas être modifié")))

